import React, { useEffect, useState } from 'react';
import {
    Box,
    FormControlLabel,
    MenuItem,
    Select,
    TextField,
    Typography,
    Checkbox,
    RadioGroup,
    Radio,
    FormLabel,
    FormGroup
} from '@mui/material';

// Import the API function to fetch forms
import { fetchForms } from '../api/formApi';

const PreviewDynamicForm = () => {
    const [forms, setForms] = useState([]);
    const [selectedForm, setSelectedForm] = useState(null);

    useEffect(() => {
        // Fetch forms from the database when the component mounts
        fetchForms()
            .then(data => {
                setForms(data);
            })
            .catch(error => {
                console.error('Error fetching forms:', error);
                alert('Failed to load forms.');
            });
    }, []);

    const handleFormSelect = (event) => {
        const formId = event.target.value;
        const formObject = forms.find((f) => f.id === parseInt(formId, 10)); // Use 'id' from your data
        setSelectedForm(formObject?.form_data || null); // Access form_data
    };

    return (
        <Box p={2}>
            {/* Form Selection Dropdown */}
            <Box mb={3}>
                <Typography variant="h6" gutterBottom>Select a Form to Preview</Typography>
                <Select
                    value={selectedForm?.formName || ''}
                    onChange={handleFormSelect}
                    displayEmpty
                    fullWidth
                >
                    <MenuItem value="" disabled>Select Form</MenuItem>
                    {forms.map((form) => (
                        <MenuItem key={form.id} value={form.id}> {/* Use 'id' as value */}
                            {form.form_data?.formName} {/* Access formName from form_data */}
                        </MenuItem>
                    ))}
                </Select>
            </Box>

            {/* Form Preview */}
            {selectedForm && (
                <Box>
                    {/* Form Name */}
                    <Typography variant="h5" gutterBottom>
                        {selectedForm.formName}
                    </Typography>

                    {/* Form Description */}
                    <Typography variant="subtitle1" gutterBottom>
                        {selectedForm.formDescription}
                    </Typography>

                    {/* Form Fields */}
                    <form>
                        {selectedForm.fields.map((field, index) => (
                            <Box key={index} mb={2}>
                                {/* Text / Number / Password Fields */}
                                {(field.controlType === 'text' ||
                                    field.controlType === 'number' ||
                                    field.controlType === 'email' ||
                                    field.controlType === 'password') && (
                                        <TextField
                                            label={field.label}
                                            type={field.controlType}
                                            placeholder={field.placeholder}
                                            required={field.validations?.includes('required')}
                                            inputProps={{
                                                minLength: field.minLength || undefined,
                                                maxLength: field.maxLength || undefined,
                                            }}
                                            helperText={field.helperText}
                                            fullWidth
                                        />
                                    )}

                                {/* Checkbox Group (Vertical) */}
                                {field.controlType === 'checkbox' && (
                                    <FormGroup>
                                        <FormLabel component="legend">{field.label}</FormLabel>
                                        {field.options?.map((option, idx) => (
                                            <FormControlLabel
                                                key={idx}
                                                control={<Checkbox />}
                                                label={option}
                                            />
                                        ))}
                                    </FormGroup>
                                )}

                                {/* Radio Group (Horizontal) */}
                                {field.controlType === 'radio' && (
                                    <Box>
                                        <FormLabel component="legend">{field.label}</FormLabel>
                                        <RadioGroup row>
                                            {field.options?.map((option, idx) => (
                                                <FormControlLabel
                                                    key={idx}
                                                    value={option}
                                                    control={<Radio />}
                                                    label={option}
                                                />
                                            ))}
                                        </RadioGroup>
                                    </Box>
                                )}
                            </Box>
                        ))}
                    </form>
                </Box>
            )}
        </Box>
    );
};

export default PreviewDynamicForm;
